"""Car lists from _data/ (generated by inventory.py)."""

import json
import os

from .core import DATA, FmError

SWAP_MAKE = 160      # motores de swap (sem listing no showroom)
SWAP_IDS = {3385}


def load_cars():
    with open(os.path.join(DATA, "cars.json"), encoding="utf-8") as fh:
        return json.load(fh)


def denied_ids():
    with open(os.path.join(DATA, "denylist.json"), encoding="utf-8") as fh:
        deny = json.load(fh)
    return {c for e in deny if e.get("sempre") for c in (e.get("carros") or [])}


def showroom_ids(cars=None):
    """All cars except engine swaps (= the 682 list of mc55)."""
    cars = cars if cars is not None else load_cars()
    ids = [c["id"] for c in cars
           if c.get("make") != SWAP_MAKE and c.get("id") not in SWAP_IDS]
    if len(set(ids)) != len(ids):
        raise FmError("cars.json with duplicated ids")
    return ids


def guid(car_id):
    return "00000001-0000-0000-0000-%012d" % car_id


def check_acceptlist(car_ids, cheap_max=100000, cars=None):
    """F3 1.7: known ids, none always-denied (error); warns without a cheap car.
    Returns a list of warnings."""
    cars = cars if cars is not None else load_cars()
    by_id = {c["id"]: c for c in cars}
    unknown = [c for c in car_ids if c not in by_id]
    if unknown:
        raise FmError("unknown car ids: %s" % unknown[:10])
    denied = sorted(set(car_ids) & denied_ids())
    warnings = []
    if denied:
        warnings.append("acceptlist has always-denied cars %s (CarDenyLists) "
                        "- they are skipped by the game" % denied[:10])
    if not any(by_id[c]["price"] <= cheap_max for c in car_ids):
        warnings.append("no car <= %d cr in the acceptlist (F3 1.7)" % cheap_max)
    return warnings
